const GMHM_PEAK_ALPHA     = 0.92;  // 컷인 최대 불투명도 (플레이어 시야 확보)
// 손끝 오프셋: 컷인 이미지 중심(플레이어) 기준. dirX 방향으로 뻗은 손 위치 근사치
const HAND_OFFSET_X_RATIO = 0.34;  // 표시 폭 대비 손끝 x
const HAND_OFFSET_Y_RATIO = 0.24;  // 표시 높이 대비 손끝 y (위쪽이라 음수 적용)
const BEAM_LENGTH         = 780;   // 빔 길이 (화면 대각선보다 김 → 화면 밖까지)
const BEAM_HALF_WIDTH     = 34;    // 빔 반경 (경로상 똥 제거 판정)

export class KAbility extends BaseAbility {
  // score가 한 번에 여러 점 뛰어도 같은 마일스톤에서 두 번 발동하지 않도록 가드
  private lastGmhmScore = 0;

  onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % K_PARAMS.gmhmInterval !== 0) return;
    if (score <= this.lastGmhmScore) return;
    this.lastGmhmScore = score;
    this._fireGmhm(api);
  }

