import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { K_PARAMS } from '../config/abilityParams';

// ── K (아빠) 능력 ────────────────────────────────────────────────────────
// 300점마다 ktei_ss_gmhm(각성 발사 포즈) 컷인이 뜨고, 손끝에서 위 대각선으로
// 에너지파를 발사한다. 화면 중앙 기준 플레이어가 왼쪽이면 오른쪽 위, 오른쪽이면
// 왼쪽 위로 발사되며 빔 경로상의 일반 똥을 제거한다.
//
// 아들 동반자(ktei)는 항상 k와 같은 크기로 땅에서 뒤를 따라다니며(간격 유지, 겹침 없음)
// 특수똥을 수집한다 (일반 똥은 통과 — 아들은 게임오버 유발 안 함).
// k가 죽으면(첫 피격) 게임오버 대신 아들이 각성해 ktei_ss 본체로 승계된다 — 1회 한정.
// 승계 후 본체는 다른 캐릭터보다 살짝 공중에 뜨지만 조작은 좌우만(기존과 동일).

const GMHM_DISPLAY_W      = 120;   // 컷인 이미지 표시 폭 (원본 768×1344 = 4:7)
const GMHM_DISPLAY_H      = 210;   // 표시 높이 (비율 유지)
const GMHM_PEAK_ALPHA     = 0.92;  // 컷인 최대 불투명도 (플레이어 시야 확보)
// 손끝 오프셋: 컷인 이미지 중심(플레이어) 기준. dirX 방향으로 뻗은 손 위치 근사치
const HAND_OFFSET_X_RATIO = 0.34;  // 표시 폭 대비 손끝 x
const HAND_OFFSET_Y_RATIO = 0.24;  // 표시 높이 대비 손끝 y (위쪽이라 음수 적용)
const BEAM_LENGTH         = 780;   // 빔 길이 (화면 대각선보다 김 → 화면 밖까지)
const BEAM_HALF_WIDTH     = 34;    // 빔 반경 (경로상 똥 제거 판정)

// 아들(ktei) 동반자
const SON_SCALE    = 0.5;    // 플레이어 대비 크기 (반 사이즈)
const SON_FOLLOW   = 0.14;   // x 추적 lerp 계수 (작을수록 더 느리게 뒤따름)
const SON_Y_OFFSET = -8;     // 플레이어보다 살짝 위 (뒤에 있는 느낌)
const SON_FACE_EPS = 1.2;    // 좌우 방향 전환 최소 이동량 (px/frame)
const SON_BOB_AMP  = 2;      // 상하 바운스 진폭

// 사망 승계 (ktei_ss)
const SUCCESSION_LIFT          = 64;   // 승계 후 본체를 공중으로 띄우는 높이 (px)
const SUCCESSION_INVINCIBLE_MS = 1500; // 승계 순간 무적 (즉사 방지)

export class KAbility extends BaseAbility {
  // score가 한 번에 여러 점 뛰어도 같은 마일스톤에서 두 번 발동하지 않도록 가드
  private lastGmhmScore = 0;

  // 아들(ktei) 동반자 — onCreate에서 생성, onUpdate에서 추적, onDestroy에서 정리
  private son?: Phaser.GameObjects.Image;
  private sonDir: string = 'front';

  // 사망 승계 여부 (1회만 승계 → 이후 정상 게임오버)
  private transformed = false;

  // ── 아들 동반자: 생성 + 추적 ───────────────────────────────────────────
  onCreate(api: GameSceneAPI): void {
    const { scene, player } = api;
    this.son = scene.add.image(player.x, player.y + SON_Y_OFFSET, 'ktei_front')
      .setDisplaySize(player.displayWidth * SON_SCALE, player.displayHeight * SON_SCALE);
    // 배경 위 · 플레이어 뒤로 배치 (배경·플레이어·아들 모두 depth 0 → 표시 순서로 제어)
    scene.children.moveBelow(this.son, player);
  }

  onUpdate(api: GameSceneAPI): void {
    const son = this.son;
    if (!son || !son.active) return;
    const { scene, player } = api;

    // 플레이어 x를 부드럽게 뒤따름 (이동 시 자연스럽게 뒤처지고, 멈추면 따라붙음)
    const prevX = son.x;
    son.x = Phaser.Math.Linear(son.x, player.x, SON_FOLLOW);
    // 살짝 위 + 미세한 상하 바운스
    const bob = Math.sin(scene.time.now / 220) * SON_BOB_AMP;
    son.y = Phaser.Math.Linear(son.y, player.y + SON_Y_OFFSET + bob, 0.2);

    // 이동 방향으로 좌우 스프라이트 전환 (거의 멈추면 정면)
    const dx = son.x - prevX;
    const dir = dx > SON_FACE_EPS ? 'right' : dx < -SON_FACE_EPS ? 'left' : 'front';
    if (dir !== this.sonDir) {
      son.setTexture(`ktei_${dir}`);
      this.sonDir = dir;
    }
  }

  onDestroy(_api: GameSceneAPI): void {
    this.son?.destroy();
    this.son = undefined;
  }

  // ── 사망 승계: k 죽으면 아들이 각성해 본체가 됨 (1회) ────────────────────
  // true 반환 시 GameScene이 게임오버를 취소하고 피격 똥을 회수한다.
  onHitPoop(api: GameSceneAPI): boolean {
    if (this.transformed) return false; // 이미 승계됨 → 정상 게임오버
    this.transformed = true;
    this._succeedToKteiSs(api);
    return true;
  }

  private _succeedToKteiSs(api: GameSceneAPI): void {
    const { scene, player } = api;

    // 아들이 본체로 승계 → 작은 동반자 제거
    this.son?.destroy();
    this.son = undefined;

    // 각성형 스프라이트로 교체 + 살짝 공중으로 (조작은 기존 좌우 그대로)
    player.setTexturePrefix('ktei_ss_');
    player.setY(player.y - SUCCESSION_LIFT);

    // 승계 순간 보호 + 화면 정리 (승계 직후 즉사·불공정 방지)
    player.setInvincibleBriefly(SUCCESSION_INVINCIBLE_MS);
    this._clearAllPoops(api);

    // 각성 연출: 금빛 섬광 + 확장 링 + 버스트
    this._succeedEffect(scene, player.x, player.y);
  }

  private _clearAllPoops(api: GameSceneAPI): void {
    const { poops, scene } = api;
    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[]).filter(p => p.active);
    const positions = targets.map(p => ({ x: p.x, y: p.y }));
    targets.forEach(p => (p as unknown as PoolablePoopBase).recycle());
    positions.forEach(({ x, y }) => this._spawnBurst(scene, x, y, 12));
  }

  private _succeedEffect(scene: Phaser.Scene, x: number, y: number): void {
    // 전체 화면 금빛 섬광
    const flash = scene.add.rectangle(
      scene.scale.width / 2, scene.scale.height / 2,
      scene.scale.width, scene.scale.height, 0xffe066, 0.5,
    ).setDepth(318);
    scene.tweens.add({
      targets: flash, alpha: 0, duration: 380,
      onComplete: () => { if (flash.active) flash.destroy(); },
    });

    // 플레이어 중심 확장 링
    const ring = scene.add.graphics({ x, y }).setDepth(319);
    ring.lineStyle(5, 0xffd23a, 0.95);
    ring.strokeCircle(0, 0, 20);
    scene.tweens.add({
      targets: ring, scaleX: 4, scaleY: 4, alpha: 0, duration: 480, ease: 'Quad.easeOut',
      onComplete: () => { if (ring.active) ring.destroy(); },
    });

    this._spawnBurst(scene, x, y, 30);
  }

  onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % K_PARAMS.gmhmInterval !== 0) return;
    if (score <= this.lastGmhmScore) return;
    this.lastGmhmScore = score;
    this._fireGmhm(api);
  }

  // ── 에너지파 발사 ──────────────────────────────────────────────────────
  private _fireGmhm(api: GameSceneAPI): void {
    const { scene, player } = api;
    const cx = scene.scale.width / 2;

    // 중앙 기준 왼쪽 → 오른쪽 위 대각선(+1), 오른쪽 → 왼쪽 위 대각선(-1)
    const onLeft = player.x < cx;
    const dirX   = onLeft ? 1 : -1;
    // 방향에 맞는 손 뻗은 스프라이트 (left는 right의 좌우 미러본)
    const texKey = onLeft ? 'ktei_ss_gmhm_right' : 'ktei_ss_gmhm_left';

    const px = player.x;
    const py = player.y;

    // 컷인 이미지 — 팝인 후 짧게 유지하고 페이드아웃
    const img = scene.add.image(px, py, texKey)
      .setDisplaySize(GMHM_DISPLAY_W, GMHM_DISPLAY_H)
      .setDepth(320)
      .setAlpha(0);
    scene.tweens.add({ targets: img, alpha: GMHM_PEAK_ALPHA, duration: 110, ease: 'Quad.easeOut' });
    scene.tweens.add({
      targets: img, alpha: 0, delay: 560, duration: 240, ease: 'Quad.easeIn',
      onComplete: () => { if (img.active) img.destroy(); },
    });

    // 손 끝 좌표 (위 대각선으로 뻗은 손)
    const handX = px + dirX * GMHM_DISPLAY_W * HAND_OFFSET_X_RATIO;
    const handY = py - GMHM_DISPLAY_H * HAND_OFFSET_Y_RATIO;

    // 45° 위 대각선 단위 벡터
    const inv = 1 / Math.SQRT2;
    const ux = dirX * inv;
    const uy = -inv;

    this._fireBeam(scene, handX, handY, ux, uy);
    this._clearPoopsAlongBeam(api, handX, handY, ux, uy);
  }

  // ── 빔 비주얼 (손끝에서 뻗어나가는 3중 글로우 라인) ───────────────────────
  private _fireBeam(
    scene: Phaser.Scene,
    ox: number, oy: number, ux: number, uy: number,
  ): void {
    const g = scene.add.graphics().setDepth(315);
    const state = { t: 0, fade: 1 };

    const redraw = () => {
      if (!g.active) return;
      g.clear();
      const ex = ox + ux * BEAM_LENGTH * state.t;
      const ey = oy + uy * BEAM_LENGTH * state.t;
      const a = state.fade;
      g.lineStyle(24, 0x3aa0ff, 0.22 * a); g.lineBetween(ox, oy, ex, ey); // 바깥 글로우
      g.lineStyle(13, 0x8fd4ff, 0.50 * a); g.lineBetween(ox, oy, ex, ey); // 중간
      g.lineStyle(5,  0xffffff, 0.95 * a); g.lineBetween(ox, oy, ex, ey); // 코어
    };

    // 1) 빔이 손끝에서 뻗어나감
    scene.tweens.add({ targets: state, t: 1, duration: 150, ease: 'Quad.easeOut', onUpdate: redraw });
    // 2) 잠깐 유지 후 페이드아웃
    scene.tweens.add({
      targets: state, fade: 0, delay: 210, duration: 220, ease: 'Quad.easeIn',
      onUpdate: redraw,
      onComplete: () => { if (g.active) g.destroy(); },
    });

    this._spawnBurst(scene, ox, oy, 18); // 손끝 머즐 플래시
  }

  // ── 빔 경로상 일반 똥 제거 ─────────────────────────────────────────────
  private _clearPoopsAlongBeam(
    api: GameSceneAPI,
    ox: number, oy: number, ux: number, uy: number,
  ): void {
    const { poops, scene } = api;
    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => {
        if (!p.active) return false;
        const rx = p.x - ox;
        const ry = p.y - oy;
        const along = rx * ux + ry * uy;             // 빔 방향 투영(전방 거리)
        if (along < 0 || along > BEAM_LENGTH) return false;
        const perp = Math.abs(rx * uy - ry * ux);    // 빔 직선까지 수직 거리
        return perp <= BEAM_HALF_WIDTH;
      });

    if (targets.length === 0) return;

    // 위치 저장 후 즉시 재활용 (똥은 오브젝트 풀 — destroy 아님)
    const positions = targets.map(p => ({ x: p.x, y: p.y }));
    targets.forEach(p => (p as unknown as PoolablePoopBase).recycle());

    positions.forEach(({ x, y }) => this._spawnBurst(scene, x, y, 12));
    api.addAbilityBonus(positions.length * K_PARAMS.beamPointsPerPoop);
  }

  // ── 스파크 버스트 (머즐/피격 공용) ─────────────────────────────────────
  private _spawnBurst(scene: Phaser.Scene, x: number, y: number, radius: number): void {
    const g = scene.add.graphics({ x, y }).setDepth(316);
    g.fillStyle(0xffffff, 0.95); g.fillCircle(0, 0, radius * 0.5);
    g.fillStyle(0x8fd4ff, 0.45); g.fillCircle(0, 0, radius);
    g.lineStyle(2, 0xdff2ff, 0.9);
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      g.lineBetween(0, 0, Math.cos(a) * radius * 0.9, Math.sin(a) * radius * 0.9);
    }
    scene.tweens.add({
      targets: g, alpha: 0, scaleX: 1.7, scaleY: 1.7, duration: 280, ease: 'Quad.easeOut',
      onComplete: () => { if (g.active) g.destroy(); },
    });
  }
}

