// ── 아들 동반자: 생성 + 추적 + 특수똥 수집 ─────────────────────────────
onCreate(api: GameSceneAPI): void {
  const { scene, player } = api;

  // 플레이어와 같은 크기, 땅(같은 y)에서 뒤(간격 SON_GAP)에 배치
  const son = scene.physics.add.sprite(player.x + this.sonSide * SON_GAP, player.y, 'ktei_front');
  son.setDisplaySize(player.displayWidth, player.displayHeight);
  (son.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);
  // 배경 위 · 플레이어 뒤로 배치 (표시 순서로 제어)
  scene.children.moveBelow(son, player);

  // 특수 똥은 아들이 닿으면 수집 (일반 똥은 overlap 미등록 → 통과, 게임오버 유발 안 함)
  const makeCollect = (
    fn: (p: Phaser.Physics.Arcade.Sprite) => void,
  ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback => (_s, p) => {
    const sp = p as Phaser.Physics.Arcade.Sprite;
    if (sp.active) fn(sp);
  };
  scene.physics.add.overlap(son, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
  scene.physics.add.overlap(son, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
  scene.physics.add.overlap(son, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
  scene.physics.add.overlap(son, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));

  this.son = son;
}

onUpdate(api: GameSceneAPI): void {
  const son = this.son;
  if (!son || !son.active) return;
  const { player } = api;

  // k의 이동 방향 → 아들은 반대쪽(뒤)에 위치 (겹침 방지)
  const vx = (player.body as Phaser.Physics.Arcade.Body).velocity.x;
  if (vx > 1) this.sonSide = -1;      // k 오른쪽 이동 → 아들은 왼쪽(뒤)
  else if (vx < -1) this.sonSide = 1; // k 왼쪽 이동 → 아들은 오른쪽(뒤)

  // k로부터 SON_GAP 떨어진 뒤쪽으로 부드럽게 이동, 땅에 붙어서(공중 X)
  const prevX = son.x;
  const targetX = player.x + this.sonSide * SON_GAP;
  son.x = Phaser.Math.Linear(son.x, targetX, SON_FOLLOW);
  son.y = player.y;

  // 이동 방향으로 좌우 스프라이트 전환 (거의 멈추면 정면)
  const dx = son.x - prevX;
  const dir = dx > SON_FACE_EPS ? 'right' : dx < -SON_FACE_EPS ? 'left' : 'front';
  if (dir !== this.sonDir) {
    son.setTexture(`ktei_${dir}`);
    this.sonDir = dir;
  }
}

