import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { K_PARAMS } from '../config/abilityParams';

// ── K (아빠) 능력 ────────────────────────────────────────────────────────
// 300점마다 ktei_ss_gmhm(각성 발사 포즈) 컷인이 뜨고, 손끝에서 위 대각선으로
// 에너지파를 발사한다. 화면 중앙 기준 플레이어가 왼쪽이면 오른쪽 위, 오른쪽이면
// 왼쪽 위로 발사되며 빔 경로상의 일반 똥을 제거한다.
//
// 아들 동반자(ktei)는 항상 k와 같은 크기로 땅에서 뒤를 따라다니며(간격 유지, 겹침 없음)
// 특수똥을 수집한다 (일반 똥은 통과 — 아들은 게임오버 유발 안 함).
// k가 죽으면(첫 피격) 게임오버 대신 아들이 각성해 ktei_ss 본체로 승계된다 — 1회 한정.
// 승계 후 본체는 다른 캐릭터보다 살짝 공중에 뜨지만 조작은 좌우만(기존과 동일).

const GMHM_DISPLAY_W      = 120;   // 컷인 이미지 표시 폭 (원본 768×1344 = 4:7)
const GMHM_DISPLAY_H      = 210;   // 표시 높이 (비율 유지)
const GMHM_PEAK_ALPHA     = 0.92;  // 컷인 최대 불투명도 (플레이어 시야 확보)
// 손끝 오프셋: 컷인 이미지 중심(플레이어) 기준. dirX 방향으로 뻗은 손 위치 근사치
const HAND_OFFSET_X_RATIO = 0.34;  // 표시 폭 대비 손끝 x
const HAND_OFFSET_Y_RATIO = 0.24;  // 표시 높이 대비 손끝 y (위쪽이라 음수 적용)
const BEAM_LENGTH         = 780;   // 빔 길이 (화면 대각선보다 김 → 화면 밖까지)
const BEAM_HALF_WIDTH     = 34;    // 빔 반경 (경로상 똥 제거 판정)

// 아들(ktei) 동반자 — 플레이어와 같은 크기, 땅에서 뒤를 따라다니며 특수똥 수집
const SON_FOLLOW   = 0.16;   // x 추적 lerp 계수
const SON_GAP      = 44;     // k와 유지하는 간격 (겹침 방지, 글리치 분신보다 가깝게)
const SON_FACE_EPS = 1.2;    // 좌우 방향 전환 최소 이동량 (px/frame)

// 사망 승계 (ktei_ss)
const SUCCESSION_LIFT          = 21;   // 승계 후 본체를 살짝 띄우는 높이 (px) — 이전 64의 1/3
const SUCCESSION_INVINCIBLE_MS = 1500; // 승계 순간 무적 (즉사 방지)

export class KAbility extends BaseAbility {
  // score가 한 번에 여러 점 뛰어도 같은 마일스톤에서 두 번 발동하지 않도록 가드
  private lastGmhmScore = 0;

  // 아들(ktei) 동반자 — onCreate에서 생성, onUpdate에서 추적, onDestroy에서 정리
  private son?: Phaser.Physics.Arcade.Sprite;
  private sonDir: string = 'front';
  private sonSide = -1; // k 기준 아들이 있는 쪽 (-1 왼쪽 / +1 오른쪽) = k 이동 방향의 반대

  // 사망 승계 여부 (1회만 승계 → 이후 정상 게임오버)
  private transformed = false;

  // ── 아들 동반자: 생성 + 추적 + 특수똥 수집 ─────────────────────────────
  onCreate(api: GameSceneAPI): void {
    const { scene, player } = api;

    // 플레이어와 같은 크기, 땅(같은 y)에서 뒤(간격 SON_GAP)에 배치
    const son = scene.physics.add.sprite(player.x + this.sonSide * SON_GAP, player.y, 'ktei_front');
    son.setDisplaySize(player.displayWidth, player.displayHeight);
    (son.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);
    // 배경 위 · 플레이어 뒤로 배치 (표시 순서로 제어)
    scene.children.moveBelow(son, player);

    // 특수 똥은 아들이 닿으면 수집 (일반 똥은 overlap 미등록 → 통과, 게임오버 유발 안 함)
    const makeCollect = (
      fn: (p: Phaser.Physics.Arcade.Sprite) => void,
    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback => (_s, p) => {
      const sp = p as Phaser.Physics.Arcade.Sprite;
      if (sp.active) fn(sp);
    };
    scene.physics.add.overlap(son, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
    scene.physics.add.overlap(son, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
    scene.physics.add.overlap(son, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
    scene.physics.add.overlap(son, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));

    this.son = son;
  }

  onUpdate(api: GameSceneAPI): void {
    const son = this.son;
    if (!son || !son.active) return;
    const { player } = api;

    // k의 이동 방향 → 아들은 반대쪽(뒤)에 위치 (겹침 방지)
    const vx = (player.body as Phaser.Physics.Arcade.Body).velocity.x;
    if (vx > 1) this.sonSide = -1;      // k 오른쪽 이동 → 아들은 왼쪽(뒤)
    else if (vx < -1) this.sonSide = 1; // k 왼쪽 이동 → 아들은 오른쪽(뒤)

    // k로부터 SON_GAP 떨어진 뒤쪽으로 부드럽게 이동, 땅에 붙어서(공중 X)
    const prevX = son.x;
    const targetX = player.x + this.sonSide * SON_GAP;

