const BEAM_HALF_WIDTH = 34;    // 빔 반경 (경로상 똥 제거 판정)
const HAND_X_RATIO    = 0.22;  // 플레이어 폭 대비 손끝 x 오프셋 (발사 방향쪽)
const HAND_Y_RATIO    = 0.34;  // 플레이어 높이 대비 손끝 y 오프셋 (위쪽)

// 태이(ktei) 크기 — 아들 동반자 + 초사이언 본체 공용. 아빠(k)의 80% 크기
const KTEI_SCALE = 0.8;

// 아들(ktei) 동반자
