// 캐릭터 주변 파란·노란 파지직 (좌표는 매 프레임 갱신 — 멈춰 있어도 안전)
// 몸통 바깥 링에서 방출되게 그려 캐릭터 그림에 묻히지 않도록 함
private _crackleAround(
  scene: Phaser.Scene, getX: () => number, getY: () => number, radius: number,
): void {
  this._runCrackle(scene, 318, g => {
    const cx = getX(), cy = getY();
    const bolts = 12;
    for (let i = 0; i < bolts; i++) {
      // 링 둘레에 고르게 분포 + 약간 흔들기 → 몸통을 감싸는 전기
      const a = (i / bolts) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
      const r = Phaser.Math.FloatBetween(radius * 0.85, radius * 1.3);
      const sx = cx + Math.cos(a) * r;
      const sy = cy + Math.sin(a) * r * 0.95;
      const color = i % 2 === 0 ? SPARK_BLUE : SPARK_YELLOW;
      this._drawSpark(g, sx, sy, Phaser.Math.FloatBetween(2.2, 3.6), 16, color);
      this._drawSpark(g, sx, sy, 1, 12, 0xffffff); // 밝은 코어로 선명하게
    }
  });
}

