41	// 캐릭터가 작아 보임 → 트림 높이 비율만큼 본체를 균일 확대해 시각적 크기를 아들과 일치.
42	const SS_HEIGHT_COMP = 1166 / 1110; // ≈ 1.05
43	
44	// 아들(ktei) 동반자
45	const SON_FOLLOW   = 0.16;   // x 추적 lerp 계수
46	const SON_GAP      = 36;     // k와 유지하는 간격 (겹침 방지, 글리치 분신보다 가깝게)
47	const SON_FACE_EPS = 1.2;    // 좌우 방향 전환 최소 이동량 (px/frame)
48	
49	// 사망 승계 (ktei_ss)
50	const SUCCESSION_LIFT          = 21;   // 승계 후 본체를 살짝 띄우는 높이 (px)
51	const SUCCESSION_INVINCIBLE_MS = 1500; // 승계 순간 무적 (즉사 방지)
52	
53	export class KAbility extends BaseAbility {
54	  // score가 한 번에 여러 점 뛰어도 같은 마일스톤에서 두 번 발동하지 않도록 가드
55	  private lastGmhmScore = 0;
56	
57	  // 아들(ktei) 동반자 — onCreate에서 생성, onUpdate에서 추적, onDestroy에서 정리
58	  private son?: Phaser.Physics.Arcade.Sprite;
59	  private sonDir: string = 'front';
60	  private sonSide = -1; // k 기준 아들이 있는 쪽 (-1 왼쪽 / +1 오른쪽) = k 이동 방향의 반대
61	
62	  // 사망 승계 여부 (1회만 승계 → 이후 정상 게임오버)
63	  private transformed = false;
64	
65	  // ── 아들 동반자: 생성 + 추적 + 특수똥 수집 ─────────────────────────────
66	  onCreate(api: GameSceneAPI): void {
67	    const { scene, player } = api;
68	
69	    // '태이' 크기(아빠의 80%)로, 땅(발 라인 정렬)에서 뒤(간격 SON_GAP)에 배치
70	    const son = scene.physics.add.sprite(player.x + this.sonSide * SON_GAP, player.y, 'ktei_front');
71	    son.setDisplaySize(player.displayWidth * KTEI_SCALE, player.displayHeight * KTEI_SCALE);
72	    // 작아진 만큼 아래로 내려 발을 아빠와 같은 바닥 라인에 맞춤 (센터 원점 보정)
73	    son.setY(player.y + (player.displayHeight - son.displayHeight) / 2);
74	    (son.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);
75	    // 배경 위 · 플레이어 뒤로 배치 (표시 순서로 제어)
76	    scene.children.moveBelow(son, player);
77	
78	    // 특수 똥은 아들이 닿으면 수집 (일반 똥은 overlap 미등록 → 통과, 게임오버 유발 안 함)
79	    const makeCollect = (
80	      fn: (p: Phaser.Physics.Arcade.Sprite) => void,
81	    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback => (_s, p) => {
82	      const sp = p as Phaser.Physics.Arcade.Sprite;
83	      if (sp.active) fn(sp);
84	    };
85	    scene.physics.add.overlap(son, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
86	    scene.physics.add.overlap(son, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
87	    scene.physics.add.overlap(son, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
88	    scene.physics.add.overlap(son, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));
89	
90	    this.son = son;
91	  }
92	
93	  onUpdate(api: GameSceneAPI): void {
94	    const son = this.son;
95	    if (!son || !son.active) return;
96	    const { player } = api;
97	
98	    // k의 이동 방향 → 아들은 반대쪽(뒤)에 위치 (겹침 방지)
99	    const vx = (player.body as Phaser.Physics.Arcade.Body).velocity.x;
100	    if (vx > 1) this.sonSide = -1;      // k 오른쪽 이동 → 아들은 왼쪽(뒤)
101	    else if (vx < -1) this.sonSide = 1; // k 왼쪽 이동 → 아들은 오른쪽(뒤)
102	
103	    // k로부터 SON_GAP 떨어진 뒤쪽으로 부드럽게 이동, 땅에 붙어서(공중 X)
104	    const prevX = son.x;
105	    const targetX = player.x + this.sonSide * SON_GAP;
106	    son.x = Phaser.Math.Linear(son.x, targetX, SON_FOLLOW);
107	    son.y = player.y + (player.displayHeight - son.displayHeight) / 2; // 발을 아빠 바닥 라인에 고정
108	
109	    // 이동 방향으로 좌우 스프라이트 전환 (거의 멈추면 정면)
110	    const dx = son.x - prevX;
111	    const dir = dx > SON_FACE_EPS ? 'right' : dx < -SON_FACE_EPS ? 'left' : 'front';
112	    if (dir !== this.sonDir) {
113	      son.setTexture(`ktei_${dir}`);
114	      this.sonDir = dir;
115	    }
116	  }
117	
118	  onDestroy(_api: GameSceneAPI): void {
119	    this.son?.destroy();
120	    this.son = undefined;
121	  }
122	
123	  // ── 사망 승계: k 죽으면 아들이 각성해 본체가 됨 (1회) ────────────────────
124	  // true 반환 시 GameScene이 게임오버를 취소하고 피격 똥을 회수한다.
125	  onHitPoop(api: GameSceneAPI): boolean {
126	    if (this.transformed) return false; // 이미 승계됨 → 정상 게임오버
127	    this.transformed = true;
128	    this._succeedToKteiSs(api);
129	    return true;
