131	
132	  private _succeedToKteiSs(api: GameSceneAPI): void {
133	    const { scene, player } = api;
134	
135	    // 아들이 본체로 승계 → 작은 동반자 제거
136	    this.son?.destroy();
137	    this.son = undefined;
138	
139	    // 각성형 스프라이트로 교체 + '태이' 크기(k의 80%)로 + 살짝 공중으로 (조작은 기존 좌우 그대로)
140	    // SS_HEIGHT_COMP로 균일 확대 → 초사이언 캐릭터 겉보기 크기를 변경 전 아들과 일치
141	    player.setTexturePrefix('ktei_ss_');
142	    const kteiScale = KTEI_SCALE * SS_HEIGHT_COMP;
143	    player.resize(player.displayWidth * kteiScale, player.displayHeight * kteiScale);
144	    player.setY(player.y - SUCCESSION_LIFT);
145	
146	    // 승계 순간 보호 + 화면 정리 (승계 직후 즉사·불공정 방지)
147	    player.setInvincibleBriefly(SUCCESSION_INVINCIBLE_MS);
148	    this._clearAllPoops(api);
149	
150	    // 각성 연출: 금빛 섬광 + 확장 링 + 버스트
151	    this._succeedEffect(scene, player.x, player.y);
152	  }
153	
154	  private _clearAllPoops(api: GameSceneAPI): void {
155	    const { poops, scene } = api;
156	    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[]).filter(p => p.active);
157	    const positions = targets.map(p => ({ x: p.x, y: p.y }));
158	    targets.forEach(p => (p as unknown as PoolablePoopBase).recycle());
159	    positions.forEach(({ x, y }) => this._spawnBurst(scene, x, y, 12));

