input.old_string:
onUpdate(api: GameSceneAPI): void {
  const son = this.son;
  if (!son || !son.active) return;
  const { player } = api;

  // k의 이동 방향 → 아들은 반대쪽(뒤)에 위치 (겹침 방지)
  const vx = (player.body as Phaser.Physics.Arcade.Body).velocity.x;
  if (vx > 1) this.sonSide = -1;      // k 오른쪽 이동 → 아들은 왼쪽(뒤)
  else if (vx < -1) this.sonSide = 1; // k 왼쪽 이동 → 아들은 오른쪽(뒤)

  // k로부터 SON_GAP 떨어진 뒤쪽으로 부드럽게 이동, 땅에 붙어서(공중 X)
  const prevX = son.x;
  const targetX = player.x + this.sonSide * SON_GAP;
  son.x = Phaser.Math.Linear(son.x, targetX, SON_FOLLOW);
  son.y = player.y + (player.displayHeight - son.displayHeight) / 2; // 발을 아빠 바닥 라인에 고정

  // 이동 방향으로 좌우 스프라이트 전환 (거의 멈추면 정면)
  const dx = son.x - prevX;
  const dir = dx > SON_FACE_EPS ? 'right' : dx < -SON_FACE_EPS ? 'left' : 'front';
  if (dir !== this.sonDir) {
    son.setTexture(`ktei_${dir}`);
    this.sonDir = dir;
  }
}

