// ── 에너지파 발사 (컷인 없이 현재 캐릭터가 그대로 발사) ──────────────────
private _fireGmhm(api: GameSceneAPI): void {
  const { scene, player } = api;
  const isSs = this.transformed; // 초사이언 승계 후 여부

  // 중앙 기준 왼쪽 → 오른쪽 위 대각선(+1), 오른쪽 → 왼쪽 위 대각선(-1)
  const dirX = player.x < scene.scale.width / 2 ? 1 : -1;

  // 초사이언: 발사 순간 잠깐 멈춰서 쏨
  if (isSs) player.freeze(SS_FREEZE_MS);

  // 손 끝 좌표 — 현재 캐릭터의 상체(발사 방향쪽)에서 시작
  const handX = player.x + dirX * player.displayWidth * HAND_X_RATIO;
  const handY = player.y - player.displayHeight * HAND_Y_RATIO;

  // 45° 위 대각선 단위 벡터
  const inv = 1 / Math.SQRT2;
  const ux = dirX * inv;
  const uy = -inv;

  const widthMul  = isSs ? SS_BEAM_WIDTH_MUL : 1;
  const halfWidth = isSs ? SS_BEAM_HALF_WIDTH : BEAM_HALF_WIDTH;

  this._fireBeam(scene, handX, handY, ux, uy, widthMul);
  this._sweepBeam(api, handX, handY, ux, uy, halfWidth);

  // 초사이언: 멈춰서 쏘므로 캐릭터 주변 원형 범위의 똥도 제거 + 파지직 번개 연출
  if (isSs) {
    this._auraEffect(scene, player.x, player.y, SS_AURA_RADIUS);
    this._clearPoopsAround(api, player.x, player.y, SS_AURA_RADIUS);
    // 빔 주변 노란 파지직 (빔 라인을 따라)
    this._crackleAlongBeam(scene, handX, handY, ux, uy, BEAM_LENGTH);
    // 캐릭터 주변 파란·노란 파지직 (멈춰 있는 동안)
    this._crackleAround(scene, () => player.x, () => player.y, player.displayHeight * 0.55);
  }
}

